ap}.manage-link:hover{color:#fff}.section-copy{min-width:0}.section-copy strong{display:block;font-size:11px;color:#dff4f7}.section-copy small{display:block;font-size:8px;color:#6d8c97;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.section-controls{display:flex;align-items:center;gap:10px}.limit-control{display:flex;align-items:center;gap:4px;color:#6f8e98;font-size:8px;white-space:nowrap}.limit-control input{width:42px;height:28px;border:1px solid rgba(104,204,235,.14);border-radius:8px;background:#071b25;color:#dff4f7;text-align:center;font-size:9px}.mode-control select,.selection-panel select{height:28px;border:1px solid rgba(104,204,235,.14);border-radius:8px;background:#071b25;color:#dff4f7;font-size:9px;padding:0 7px}.selection-panel{position:absolute;right:58px;top:48px;z-index:5;padding:8px;border:1px solid rgba(104,204,235,.18);border-radius:10px;background:#061923;box-shadow:0 12px 30px rgba(0,0,0,.3)}.selection-panel select{width:190px;height:82px}.selection-panel small{display:block;color:#6f8e98;font-size:7px;margin-top:5px}.section-controls{position:relative}.switch{position:relative;width:40px;height:22px;display:block}.switch input{opacity:0;width:0;height:0}.switch span{position:absolute;inset:0;border-radius:99px;background:#18303a;border:1px solid #31505a;cursor:pointer}.switch span:before{content:'';position:absolute;width:16px;height:16px;left:2px;top:2px;border-radius:50%;background:#78939c;transition:.2s}.switch input:checked+span{background:rgba(42,183,213,.22);border-color:rgba(86,210,238,.55)}.switch input:checked+span:before{transform:translateX(18px);background:#69e0f3}@media(max-width:600px){.builder-actions{margin-top:12px;justify-content:space-between}.hero{display:block}.back{display:inline-block;margin-top:12px}.builder-head{align-items:flex-start;flex-direction:column}.section-row{grid-template-columns:22px 36px minmax(0,1fr) auto;padding:10px}.section-controls{gap:6px}.mode-control select{height:26px}.sel