@push('scripts')<script>
(()=>{const list=document.getElementById('section-list'),fields=document.getElementById('order-fields');if(!list||!fields)return;let drag=null;let dragMoved=false;const sync=()=>{fields.innerHTML=[...list.querySelectorAll('.section-row')].map(x=>'<input type="hidden" name="section_order[]" value="'+x.dataset.key+'">').join('')};
const clearTargets=()=>list.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));
const save=()=>{sync();document.getElementById('home-builder').requestSubmit();};list.querySelectorAll('.section-row').forEach(row=>{row.addEventListener('dragstart',()=>{drag=row;dragMoved=true;row.classList.add('dragging')});row.addEventListener('dragover',e=>{e.preventDefault();row.classList.add('drop-target')});row.addEventListener('dragleave',()=>row.classList.remove('drop-target'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drop-target');if(!drag||drag===row)return;const rect=row.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)list.insertBefore(drag,row);else list.insertBefore(drag,row.nextSibling);sync()});row.addEventListener('dragend',()=>{row.classList.remove('dragging');drag=null;clearTargets();sync()});row.addEventListener('touchcancel',()=>{drag=null;dragMoved=false;clearTargets()})});sync();document.getElementById('home-builder').addEventListener('submit',sync);document.querySelectorAll('.home-mode').forEach(select=>{const panel=select.closest('.section-controls').querySelector('.selection-panel');const syncMode=()=>{if(panel)panel.hidden=select.value!=='selected'};select.addEventListener('change',syncMode);syncMode()});document.getElementById('home-builder').addEventListener('change',e=>{if(e.target.matches('input[type=checkbox]')){e.target.closest('.section-row')?.setAttribute('data-state',e.target.checked?'visible':'hidden')}})})();
</script>@endpush